input.sparql:
PREFIX brick: <http://brickschema.org/schema/1.3/brick#>
SELECT DISTINCT ?zoneName WHERE {
  ?sensor a brick:Sensor ;
          brick:hasPropertyType ?pt ;
          brick:hasSecondaryType/ref:* brick:Electrical_Power .
  ?zone ref:hasSensor/b:* ?sensor .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?sensor ?zone ?name WHERE {
  ?sensor a brick:Electric_Power_Sensor .
  ?sensor brick:isPointOf ?zone .
  OPTIONAL { ?zone rdfs:label ?name . }
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?sensor ?zone ?name ?tsid WHERE {
  ?sensor a brick:Electric_Power_Sensor ;
          brick:isPointOf ?zone .
  ?zone a brick:Zone .
  ?zone rdfs:label ?name .
  ?sensor ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?tsid .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?sensor ?zone ?name ?tsid WHERE {
  ?sensor a brick:Electric_Power_Sensor ;
          brick:isPointOf ?zone .
  ?zone rdfs:label ?name .
  ?sensor ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?tsid .
}
